import 'dotenv/config'

import { loginService, requestNewAccessTokenService, logoutService } from './auth.service.js'


//should send the access token and refresh token in json
export async function loginController(req, res) {
    try {
        const { username, password } = req.body
        const { accessToken, refreshToken } = await loginService(username, password)
        // refreshTokens.push(refreshToken)
        res.json({ accessToken: accessToken, refreshToken: refreshToken })
    }
    catch (err) {
        return res.status(401).json({ message: err.message })
    }
}

export async function requestNewAccessTokencontroller(req, res) {
    try {
        const refreshToken = req.body.refreshToken
        const accessToken = await requestNewAccessTokenService(refreshToken)
        res.json({ accessToken: accessToken })
    }
    catch (err) {
        res.status(403).json({ message: err.message })
    }
}

//other apps should tell their frontends to clear cookies
export async function logoutController(req, res) {
    try {
        const refreshToken = req.json.refreshToken
        await logoutService(refreshToken)
        // res.clearCookie('refreshToken', {
        //     ...cookieOptions
        // });    //tell the client to delete the token from their cookies
        res.sendStatus(204)
    }
    catch (err) {
        res.status(401).json({ message: err.message })
    }
}

export async function registerController(req, res) {
    //hard block anyone but user 1 from creating new users for now
    if (req.user.id != 1) {
        res.sendStatus(403)
        return
    }

    try {
        const userNameToCreate = req.body.username
        const passwordToCreate = req.body.password
        await registerService(userNameToCreate, passwordToCreate)
        res.sendStatus(201)
    }
    catch (err) {
        res.status(400).json({ message: err.message || err });
    }
}

